auto midpoint_rule = [&](double left, double right) {
        return (right - left) * f((left + right) / 2.0);
    };

    auto recursive_adaptive = [&](auto self, double left, double right, double tol, double whole) -> double {
        double mid = (left + right) / 2.0;
        double left_half = midpoint_rule(left, mid);
        double right_half = midpoint_rule(mid, right);

        if (std::abs(left_half + right_half - whole) <= 15.0 * tol) {
            return left_half + right_half + (left_half + right_half - whole) / 15.0;
        }

        return self(self, left, mid, tol / 2.0, left_half) + 
               self(self, mid, right, tol / 2.0, right_half);
    };

    return recursive_adaptive(recursive_adaptive, a, b, precision, midpoint_rule(a, b));

